{
    "classes": [
        {
            "doc": "\nThe TriangleMesh object represents all of the data defining\na triangular mesh.\n",
            "name": "TriangleMesh",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Returns the total number of nodes in the mesh",
                    "name": "nodeCount"
                },
                {
                    "doc": "Returns the node coordinates as an array of doubles where\nthey are the x, y, z components of each coordinate",
                    "name": "nodeCoordinatesAsDouble"
                },
                {
                    "doc": "Returns the node coordinates as an array of floats where\nthey are the x, y, z components of each coordinate",
                    "name": "nodeCoordinatesAsFloat"
                },
                {
                    "doc": "Returns the node coordinates as an array of Point3D objects",
                    "name": "nodeCoordinates"
                },
                {
                    "doc": "Returns the number of triangles in the mesh",
                    "name": "triangleCount"
                },
                {
                    "doc": "Returns the normal vectors of the mesh where there is a normal\nvector at each node",
                    "name": "normalVectorsAsDouble"
                },
                {
                    "doc": "Returns the normal vectors of the mesh where there is a normal\nvector at each node",
                    "name": "normalVectorsAsFloat"
                },
                {
                    "doc": "Returns the normal vectors of the mesh where there is a normal\nvector at each node",
                    "name": "normalVectors"
                },
                {
                    "doc": "Returns an array of indices that define which nodes are used\nfor each triangle",
                    "name": "nodeIndices"
                },
                {
                    "doc": "Returns the texture coordinates used when mapping a texture to\nthis face",
                    "name": "textureCoordinatesAsDouble"
                },
                {
                    "doc": "Returns the texture coordinates used when mapping a texture to\nthis face",
                    "name": "textureCoordinatesAsFloat"
                },
                {
                    "doc": "Returns the texture coordinates used when mapping a texture to\nthis face",
                    "name": "textureCoordinates"
                },
                {
                    "doc": "Returns the surface tolerance that was used to generate this mesh",
                    "name": "surfaceTolerance"
                }
            ],
            "type": "class"
        },
        {
            "doc": "Used to calculate new meshes for a B-Rep or T-Spline using defined criteria.",
            "functions": [
                {
                    "doc": "This is a simplified way to set the various settings that control the resulting mesh",
                    "name": "setQuality"
                },
                {
                    "doc": "Calculates a new triangle mesh based on the current settings",
                    "name": "calculate"
                }
            ],
            "name": "TriangleMeshCalculator",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Specifies the maximum distance that the mesh can deviate from the smooth surface",
                    "name": "surfaceTolerance"
                },
                {
                    "doc": "Specifies the maximum side length of any triangle in the mesh",
                    "name": "maxSideLength"
                },
                {
                    "doc": "Specifies the maximum length to height ratio that a triangle can have",
                    "name": "maxAspectRatio"
                },
                {
                    "doc": "Specifies the maximum deviation between adjacent vertex normals",
                    "name": "maxNormalDeviation"
                },
                {
                    "doc": "Returns the parent MeshManager object",
                    "name": "parentMeshManager"
                }
            ],
            "type": "class"
        }
    ],
    "message": "API documentation query completed",
    "success": true
}

{
    "members": [
        {
            "class": "Occurrence",
            "doc": "Returns the body proxies for the B-Rep bodies in the component referenced by this occurrence.\nFor example if you get the occurrences from the root component and then use this property to\nget the bodies from those occurrences, the bodies returned will return information in the context of the root\ncomponent, not the component they actually exist in.",
            "name": "bRepBodies",
            "namespace": "adsk.fusion",
            "readonly": true,
            "type": "property"
        },
        {
            "class": "Occurrence",
            "doc": "Gets and sets the 3d matrix data that defines this occurrences orientation and\nposition in its assembly context. This property replaces the transform property, which\nhas been retired because there are cases where it returns the incorrect results.",
            "name": "transform2",
            "namespace": "adsk.fusion",
            "type": "property"
        }
    ],
    "message": "API documentation query completed",
    "success": true
}
